export function audioLevel(samples){let sum=0,peak=0;for(const n of samples){const value=Number.isFinite(n)?n:0;sum+=value*value;peak=Math.max(peak,Math.abs(value));}const rms=samples.length?Math.sqrt(sum/samples.length):0;return {peak:Math.min(1,peak),rms,state:peak>=0.98?'Possible overload — move away from the microphone':rms>=0.01?'Audio signal present':'Very quiet or silent — speak or check the selected microphone'};}
